#include <bits/stdc++.h>
#define inf 17446744073709551616ull
#define ull unsigned long long
using namespace std;

ull modulus, dp_table[18][250005];
ull factorial[250005], inv_factorial[250005];
ull total_n, total_k;

ull fast_pow(ull base, ull exponent) {
    ull result = 1ULL;
    while (exponent > 0) {
        if (exponent & 1ULL) result = (result * base) % modulus;
        base = (base * base) % modulus;
        exponent >>= 1ULL;
    }
    return result;
}

ull combination(int a, int b) {
    return (((factorial[a] * inv_factorial[b]) % modulus) * inv_factorial[a - b]) % modulus;
}

ull solve() {
    int i, j, l;
    factorial[0] = 1ULL;
    for (i = 1; i <= n; i++) {
        factorial[i] = (factorial[i - 1] * (ull)i) % modulus;
    }
    inv_factorial[n] = fast_pow(factorial[n], modulus - 2ULL);
    for (i = n - 1; i >= 0; i--) {
        inv_factorial[i] = (inv_factorial[i + 1] * (ull)(i + 1)) % modulus;
    }
    for (i = 1; i <= n; i++) {
        dp_table[1][i] = inv_factorial[i];
    }
    ull result = dp_table[1][n] * combination(k, 1) % modulus;
    int limit = min(17, (int)k);
    for (i = 2; i <= limit; i++) {
        for (j = n; j; j = (j - 1) & n) {
            for (l = j; l; l = (l - 1) & j) {
                dp_table[i][j] += dp_table[i - 1][j ^ l] * inv_factorial[l];
                if (dp_table[i][j] > inf) dp_table[i][j] %= modulus;
            }
            dp_table[i][j] %= modulus;
        }
        result += dp_table[i][n] * combination(k, i);
        result %= modulus;
    }
    result *= factorial[n];
    result %= modulus;
    return result;
}

int main() {
    cin >> n >> k >> modulus;
    ull answer = fast_pow(k, n);
    if (n & 1) {
        cout << answer << endl;
        return 0;
    }
    answer = (answer - solve() + modulus) % modulus;
    cout << answer << endl;
    return 0;
}
